#include <iostream>
using namespace std;

int main() {
    int drift, step;
    cin >> drift >> step;

    while (drift > 5) {
        drift -= step;
        cout << "CALIBRATING: " << drift << endl;
    }
    cout << "SENSOR STABILIZED" << endl;

    return 0;
}

