using namespace std;

int main() {
    int max_sectors;
    cin >> max_sectors;

    int completed = 0;
    for (int s = 1; s <= max_sectors; s++) {
        int temp;
        cin >> temp;
        if (temp >= 100) {
            cout << "THERMAL SPIKE AT SECTOR " << s << endl;
            break;
        }
        completed++;
        cout << "SECTOR " << s << ": NOMINAL" << endl;
    }
    cout << "COMPLETED SECTORS: " << completed << endl;

    return 0;
}

